 "content": "def transform(grid):
    """For a half-length horizontal run, preserve it and color the missing half 1."""
    out = [row[:] for row in grid]
    width = len(out[0]) if out else 0
    for row in out:
        if width % 2 == 0 and len(row) == width:
            half = width // 2
            if all(v == row[0] for v in row[:half]) and all(v == row[0] for v in row[half:]):
                # A uniform row is not the incomplete marker.
                continue
            if all(v == row[0] for v in row[:half]) and len(set(row[half:])) == 1:
                # Demo marker: the second half is background rather than run color.
                if row[half] != row[0]:
                    row[half:] = [1] * half
    return out
